SELECT brand_group, launch_quarter, product_count FROM (SELECT CASE WHEN brand IN ('Acme', 'Umbrella') THEN 'tier_1' ELSE 'other' END AS brand_group, QUARTER(launch_date) AS launch_quarter, COUNT(*) AS product_count FROM products GROUP BY CASE WHEN brand IN ('Acme', 'Umbrella') THEN 'tier_1' ELSE 'other' END, QUARTER(launch_date)) AS x WHERE product_count >= 10 ORDER BY product_count DESC;
